using UnityEngine;
using UnityEngine.SceneManagement;

/// <summary>
/// Scene flow and gameplay loop for the Space Explorer lab assignment.
/// MainMenu, Gameplay and EndGame are real Unity scenes generated by the editor setup script.
/// </summary>
public class SpaceExplorerSceneController : MonoBehaviour
{
    public const string MainMenuSceneName = "MainMenu";
    public const string GameplaySceneName = "Gameplay";
    public const string EndGameSceneName = "EndGame";

    public static SpaceExplorerSceneController Instance { get; private set; }
    public static int CurrentScore { get; private set; }
    public static int FinalScore { get; private set; }

    public float WorldHalfWidth => gameCamera != null ? gameCamera.orthographicSize * gameCamera.aspect : 8.8f;
    public float WorldTop => gameCamera != null ? gameCamera.orthographicSize : 5f;
    public float WorldBottom => -WorldTop;
    public bool CanRunGameplay => SceneManager.GetActiveScene().name == GameplaySceneName && !paused && !transitioning;

    private Camera gameCamera;
    private bool showInstructions;
    private bool paused;
    private bool transitioning;
    private bool sceneLoadRequested;
    private string destinationScene;
    private float fadeAlpha = 1f;
    private float asteroidSpawnTimer = 1.5f;
    private float starSpawnTimer = 1f;
    private GUIStyle titleStyle;
    private GUIStyle subtitleStyle;
    private GUIStyle bodyStyle;
    private GUIStyle buttonStyle;
    private GUIStyle scoreStyle;
    private int lastStyleHeight = -1;

    private static bool activeRun;

    private void Awake()
    {
        Instance = this;
        Time.timeScale = 1f;
        fadeAlpha = 1f;
    }

    private void Start()
    {
        ConfigureCamera();
        CreateBackdrop();

        string sceneName = SceneManager.GetActiveScene().name;
        if (sceneName == GameplaySceneName)
        {
            if (!activeRun)
            {
                CurrentScore = 0;
                FinalScore = 0;
                activeRun = true;
            }

            CreatePlayer();
            for (int i = 0; i < 7; i++)
                SpawnAsteroid();
            for (int i = 0; i < 12; i++)
                SpawnStar();
        }
    }

    private void OnDestroy()
    {
        if (Instance == this)
        {
            Instance = null;
            Time.timeScale = 1f;
        }
    }

    private void ConfigureCamera()
    {
        gameCamera = Camera.main;
        if (gameCamera == null)
        {
            GameObject cameraObject = new GameObject("Main Camera");
            cameraObject.tag = "MainCamera";
            gameCamera = cameraObject.AddComponent<Camera>();
        }

        gameCamera.orthographic = true;
        gameCamera.orthographicSize = 5f;
        gameCamera.transform.position = new Vector3(0f, 0f, -10f);
        gameCamera.clearFlags = CameraClearFlags.SolidColor;
        gameCamera.backgroundColor = new Color(0.012f, 0.022f, 0.075f);
    }

    private void CreateBackdrop()
    {
        Sprite background = SpriteFactory.Background(1);
        if (background != null)
        {
            GameObject backgroundObject = new GameObject("Space Explorer Background");
            backgroundObject.transform.position = new Vector3(0f, 0f, 5f);
            SpriteRenderer renderer = backgroundObject.AddComponent<SpriteRenderer>();
            renderer.sprite = background;
            renderer.sortingOrder = -1000;

            Vector2 size = background.bounds.size;
            float widthScale = WorldHalfWidth * 2f / Mathf.Max(0.01f, size.x);
            float heightScale = WorldTop * 2f / Mathf.Max(0.01f, size.y);
            backgroundObject.transform.localScale = Vector3.one * Mathf.Max(widthScale, heightScale);
        }

        // Decorative background stars are separate from collectible stars.
        for (int i = 0; i < 100; i++)
        {
            GameObject star = new GameObject("Background Star");
            star.transform.position = new Vector3(
                Random.Range(-WorldHalfWidth, WorldHalfWidth),
                Random.Range(WorldBottom, WorldTop),
                3f);
            star.transform.localScale = Vector3.one * Random.Range(0.025f, 0.065f);

            SpriteRenderer renderer = star.AddComponent<SpriteRenderer>();
            renderer.sprite = SpriteFactory.Star();
            renderer.color = new Color(0.62f, 0.78f, 1f, Random.Range(0.35f, 0.9f));
            renderer.sortingOrder = -100;
        }
    }

    private void CreatePlayer()
    {
        GameObject player = new GameObject("Player Spaceship");
        player.transform.position = new Vector3(0f, WorldBottom + 1.2f, 0f);
        player.transform.localScale = Vector3.one * 0.78f;

        SpriteRenderer renderer = player.AddComponent<SpriteRenderer>();
        renderer.sprite = SpriteFactory.PlayerShip();
        renderer.sortingOrder = 10;

        Rigidbody2D body = player.AddComponent<Rigidbody2D>();
        body.bodyType = RigidbodyType2D.Dynamic;
        body.gravityScale = 0f;
        body.constraints = RigidbodyConstraints2D.FreezeRotation;
        body.interpolation = RigidbodyInterpolation2D.Interpolate;

        CircleCollider2D collider = player.AddComponent<CircleCollider2D>();
        collider.isTrigger = true;
        collider.radius = 0.38f;

        player.AddComponent<SpaceExplorerPlayerController>();
    }

    public void SpawnAsteroid()
    {
        GameObject asteroid = new GameObject("Asteroid");
        Vector2 position = new Vector2(
            Random.Range(-WorldHalfWidth + 0.5f, WorldHalfWidth - 0.5f),
            Random.Range(WorldBottom + 0.5f, WorldTop - 0.5f));

        GameObject player = GameObject.Find("Player Spaceship");
        if (player != null && Vector2.Distance(position, player.transform.position) < 2f)
            position.y = WorldTop - 0.7f;

        asteroid.transform.position = position;
        float size = Random.Range(0.40f, 0.78f);
        asteroid.transform.localScale = Vector3.one * size;

        SpriteRenderer renderer = asteroid.AddComponent<SpriteRenderer>();
        renderer.sprite = SpriteFactory.Asteroid();
        renderer.sortingOrder = 4;

        Rigidbody2D body = asteroid.AddComponent<Rigidbody2D>();
        body.bodyType = RigidbodyType2D.Kinematic;
        body.gravityScale = 0f;
        body.useFullKinematicContacts = true;

        CircleCollider2D collider = asteroid.AddComponent<CircleCollider2D>();
        collider.isTrigger = true;
        collider.radius = 0.48f;

        float angle = Random.Range(0f, 360f) * Mathf.Deg2Rad;
        Vector2 velocity = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * Random.Range(0.45f, 1.25f);
        SpaceExplorerAsteroidController controller = asteroid.AddComponent<SpaceExplorerAsteroidController>();
        controller.Initialize(position, velocity);
    }

    private void SpawnStar()
    {
        GameObject star = new GameObject("Collectible Star");
        Vector2 position = new Vector2(
            Random.Range(-WorldHalfWidth + 0.45f, WorldHalfWidth - 0.45f),
            Random.Range(WorldBottom + 0.45f, WorldTop - 0.45f));

        GameObject player = GameObject.Find("Player Spaceship");
        if (player != null && Vector2.Distance(position, player.transform.position) < 1.5f)
            position.x = Mathf.Clamp(position.x + 2f, -WorldHalfWidth + 0.45f, WorldHalfWidth - 0.45f);

        star.transform.position = position;
        star.transform.localScale = Vector3.one * 0.30f;

        SpriteRenderer renderer = star.AddComponent<SpriteRenderer>();
        renderer.sprite = SpriteFactory.Star();
        renderer.color = new Color(1f, 0.88f, 0.24f);
        renderer.sortingOrder = 6;

        Rigidbody2D body = star.AddComponent<Rigidbody2D>();
        body.bodyType = RigidbodyType2D.Kinematic;
        body.gravityScale = 0f;
        body.useFullKinematicContacts = true;

        CircleCollider2D collider = star.AddComponent<CircleCollider2D>();
        collider.isTrigger = true;
        collider.radius = 0.58f;

        SpaceExplorerStarController controller = star.AddComponent<SpaceExplorerStarController>();
        controller.Initialize(position);
    }

    public Vector3 ClampPlayerPosition(Vector3 position)
    {
        position.x = Mathf.Clamp(position.x, -WorldHalfWidth + 0.35f, WorldHalfWidth - 0.35f);
        position.y = Mathf.Clamp(position.y, WorldBottom + 0.4f, WorldTop - 0.4f);
        position.z = 0f;
        return position;
    }

    public void CollectStar()
    {
        if (!CanRunGameplay)
            return;

        CurrentScore += 10;
    }

    public void PlayerHitAsteroid()
    {
        if (SceneManager.GetActiveScene().name != GameplaySceneName || transitioning)
            return;

        // The assignment requires an asteroid collision to deduct points and end the run.
        CurrentScore = Mathf.Max(0, CurrentScore - 10);
        FinalScore = CurrentScore;
        activeRun = false;
        paused = false;
        Time.timeScale = 0f;
        BeginTransition(EndGameSceneName);
    }

    private void BeginNewRun()
    {
        CurrentScore = 0;
        FinalScore = 0;
        activeRun = true;
        paused = false;
        showInstructions = false;
        Time.timeScale = 1f;
        BeginTransition(GameplaySceneName);
    }

    private void GoToMainMenu()
    {
        paused = false;
        Time.timeScale = 1f;
        BeginTransition(MainMenuSceneName);
    }

    private void SetPaused(bool shouldPause)
    {
        paused = shouldPause;
        Time.timeScale = paused ? 0f : 1f;
    }

    private void BeginTransition(string sceneName)
    {
        if (transitioning)
            return;

        destinationScene = sceneName;
        transitioning = true;
        sceneLoadRequested = false;
    }

    private void Update()
    {
        if (transitioning)
        {
            fadeAlpha = Mathf.MoveTowards(fadeAlpha, 1f, Time.unscaledDeltaTime * 2.6f);
            if (fadeAlpha >= 0.999f && !sceneLoadRequested)
            {
                sceneLoadRequested = true;
                Time.timeScale = 1f;
                SceneManager.LoadScene(destinationScene);
            }
            return;
        }

        fadeAlpha = Mathf.MoveTowards(fadeAlpha, 0f, Time.unscaledDeltaTime * 2.6f);

        if (SceneManager.GetActiveScene().name != GameplaySceneName)
            return;

        if (Input.GetKeyDown(KeyCode.Escape))
            SetPaused(!paused);

        if (paused)
            return;

        asteroidSpawnTimer -= Time.deltaTime;
        if (asteroidSpawnTimer <= 0f)
        {
            if (FindObjectsOfType<SpaceExplorerAsteroidController>().Length < 9)
                SpawnAsteroid();
            asteroidSpawnTimer = Random.Range(1.2f, 2.0f);
        }

        starSpawnTimer -= Time.deltaTime;
        if (starSpawnTimer <= 0f)
        {
            if (FindObjectsOfType<SpaceExplorerStarController>().Length < 12)
                SpawnStar();
            starSpawnTimer = Random.Range(0.8f, 1.4f);
        }
    }

    private void OnGUI()
    {
        EnsureStyles();
        string sceneName = SceneManager.GetActiveScene().name;

        if (sceneName == MainMenuSceneName)
            DrawMainMenu();
        else if (sceneName == GameplaySceneName)
            DrawGameplayHud();
        else if (sceneName == EndGameSceneName)
            DrawEndGame();

        if (fadeAlpha > 0.001f)
        {
            Color previous = GUI.color;
            GUI.color = new Color(0f, 0f, 0f, fadeAlpha);
            GUI.DrawTexture(new Rect(0f, 0f, Screen.width, Screen.height), Texture2D.blackTexture);
            GUI.color = previous;
        }
    }

    private void DrawMainMenu()
    {
        float scale = Mathf.Clamp(Screen.height / 800f, 0.75f, 1.35f);
        GUI.Label(new Rect(0f, Screen.height * 0.15f, Screen.width, 76f * scale), "SPACE EXPLORER", titleStyle);
        GUI.Label(new Rect(0f, Screen.height * 0.15f + 68f * scale, Screen.width, 40f * scale),
            "Navigate the stars. Avoid the asteroids.", subtitleStyle);

        float buttonWidth = 260f * scale;
        float buttonHeight = 52f * scale;
        float x = (Screen.width - buttonWidth) * 0.5f;
        float y = Screen.height * 0.43f;

        if (GUI.Button(new Rect(x, y, buttonWidth, buttonHeight), "PLAY", buttonStyle))
            BeginNewRun();

        if (GUI.Button(new Rect(x, y + buttonHeight + 14f * scale, buttonWidth, buttonHeight), "INSTRUCTIONS", buttonStyle))
            showInstructions = !showInstructions;

        if (showInstructions)
        {
            float panelWidth = Mathf.Min(Screen.width - 32f, 600f * scale);
            float panelHeight = 240f * scale;
            Rect panel = new Rect((Screen.width - panelWidth) * 0.5f, Screen.height * 0.29f, panelWidth, panelHeight);
            GUI.Box(panel, GUIContent.none);
            GUI.Label(new Rect(panel.x + 22f, panel.y + 16f, panel.width - 44f, panel.height - 70f),
                "ARROW KEYS  — Move the spaceship\n" +
                "SPACE  — Shoot laser bolts\n" +
                "COLLECT STARS  — Gain 10 points each\n" +
                "HIT AN ASTEROID  — Lose 10 points and end the run\n" +
                "ESC  — Pause or resume during gameplay", bodyStyle);

            if (GUI.Button(new Rect(panel.x + panel.width - 132f, panel.y + panel.height - 48f, 112f, 34f), "CLOSE", buttonStyle))
                showInstructions = false;
        }
    }

    private void DrawGameplayHud()
    {
        GUI.Box(new Rect(14f, 14f, 280f, 76f), GUIContent.none);
        GUI.Label(new Rect(28f, 22f, 245f, 32f), "SCORE: " + CurrentScore, scoreStyle);
        GUI.Label(new Rect(28f, 54f, 245f, 24f), "ARROWS: MOVE     SPACE: FIRE", bodyStyle);

        if (GUI.Button(new Rect(Screen.width - 125f, 18f, 108f, 40f), paused ? "RESUME" : "PAUSE", buttonStyle))
            SetPaused(!paused);

        if (!paused)
            return;

        Color old = GUI.color;
        GUI.color = new Color(0f, 0f, 0f, 0.78f);
        GUI.DrawTexture(new Rect(0f, 0f, Screen.width, Screen.height), Texture2D.blackTexture);
        GUI.color = old;

        float scale = Mathf.Clamp(Screen.height / 800f, 0.75f, 1.25f);
        float panelWidth = 330f * scale;
        float panelHeight = 210f * scale;
        Rect panel = new Rect((Screen.width - panelWidth) * 0.5f, (Screen.height - panelHeight) * 0.5f, panelWidth, panelHeight);
        GUI.Box(panel, GUIContent.none);
        GUI.Label(new Rect(panel.x, panel.y + 12f, panel.width, 46f), "PAUSED", subtitleStyle);

        if (GUI.Button(new Rect(panel.x + 34f * scale, panel.y + 70f * scale, panel.width - 68f * scale, 42f * scale), "RESUME", buttonStyle))
            SetPaused(false);

        if (GUI.Button(new Rect(panel.x + 34f * scale, panel.y + 124f * scale, panel.width - 68f * scale, 42f * scale), "MAIN MENU", buttonStyle))
            GoToMainMenu();
    }

    private void DrawEndGame()
    {
        float scale = Mathf.Clamp(Screen.height / 800f, 0.75f, 1.35f);
        GUI.Label(new Rect(0f, Screen.height * 0.20f, Screen.width, 70f * scale), "MISSION OVER", titleStyle);
        GUI.Label(new Rect(0f, Screen.height * 0.20f + 82f * scale, Screen.width, 52f * scale),
            "FINAL SCORE: " + FinalScore, subtitleStyle);
        GUI.Label(new Rect(0f, Screen.height * 0.20f + 132f * scale, Screen.width, 42f * scale),
            "An asteroid ended this flight. Try again!", bodyStyle);

        float buttonWidth = 260f * scale;
        float buttonHeight = 50f * scale;
        float x = (Screen.width - buttonWidth) * 0.5f;
        float y = Screen.height * 0.54f;

        if (GUI.Button(new Rect(x, y, buttonWidth, buttonHeight), "MAIN MENU", buttonStyle))
            GoToMainMenu();

        if (GUI.Button(new Rect(x, y + buttonHeight + 14f * scale, buttonWidth, buttonHeight), "QUIT", buttonStyle))
            QuitGame();
    }

    private void QuitGame()
    {
#if UNITY_EDITOR
        UnityEditor.EditorApplication.isPlaying = false;
#else
        Application.Quit();
#endif
    }

    private void EnsureStyles()
    {
        if (titleStyle != null && lastStyleHeight == Screen.height)
            return;

        lastStyleHeight = Screen.height;
        float scale = Mathf.Clamp(Screen.height / 800f, 0.75f, 1.35f);
        titleStyle = new GUIStyle(GUI.skin.label)
        {
            fontSize = Mathf.RoundToInt(44f * scale),
            fontStyle = FontStyle.Bold,
            alignment = TextAnchor.MiddleCenter,
            normal = { textColor = new Color(0.34f, 0.88f, 1f) }
        };
        subtitleStyle = new GUIStyle(GUI.skin.label)
        {
            fontSize = Mathf.RoundToInt(23f * scale),
            alignment = TextAnchor.MiddleCenter,
            normal = { textColor = new Color(0.90f, 0.95f, 1f) }
        };
        bodyStyle = new GUIStyle(GUI.skin.label)
        {
            fontSize = Mathf.RoundToInt(17f * scale),
            alignment = TextAnchor.MiddleCenter,
            wordWrap = true,
            normal = { textColor = new Color(0.84f, 0.89f, 1f) }
        };
        buttonStyle = new GUIStyle(GUI.skin.button)
        {
            fontSize = Mathf.RoundToInt(18f * scale),
            fontStyle = FontStyle.Bold,
            alignment = TextAnchor.MiddleCenter,
            normal = { textColor = Color.white }
        };
        scoreStyle = new GUIStyle(GUI.skin.label)
        {
            fontSize = Mathf.RoundToInt(22f * scale),
            fontStyle = FontStyle.Bold,
            alignment = TextAnchor.MiddleLeft,
            normal = { textColor = new Color(1f, 0.86f, 0.25f) }
        };
    }
}
